//! TF_DS_TAPS_PACKED (off by default): the prompt's DSpark taps written straight into the drafter's row-major
//! [rows, taps * D] layout (`absorb`'s, the decode rounds' `rd.taps` layout), the chunk-completion copies gone.
//! Off: the planar [taps, cap, D] planes the copies gather side by side. Pure: no cuda import; the switch is
//! `Ops.taps_packed` and the call sites are `prompt.tap` (the write), `Model.sliceRun` and layer_main (the
//! completion copies and their fixture checks). No kernel: `Exact.hcMean4` already takes the output stride.
//! A malformed switch refuses startup.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_TAPS_PACKED";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadTapsPacked}!bool {
    return parse(text) orelse error.BadTapsPacked;
}

// -- host reference: the two layouts ------------------------------------------------------------------------------------------
//
// Both hold every tap's rows of D bf16 the hcMean4 write produces, as element indices of one flat buffer. Planar:
// tap j owns plane j ([taps, cap, D]); packed: row i is taps * D wide, tap j the columns j * D ..

/// Where tap j's row i's column k lands in the planar planes (the off path's `ch.taps`, `prompt.tapRows`).
pub fn planarElem(j: usize, i: usize, k: usize, cap: usize, d: usize) usize {
    return (j * cap + i) * d + k;
}

/// Where the same value lands in the packed rows ([cap, taps * D]: the completion copies' `dr.at`, `absorb`'s read
/// and, under the switch, `ch.taps` itself - the decode rounds' `rd.taps` layout).
pub fn packedElem(j: usize, i: usize, k: usize, ntaps: usize, d: usize) usize {
    return i * ntaps * d + j * d + k;
}

test "a malformed switch refuses startup" {
    try std.testing.expectEqual(@as(?bool, false), parse(null));
    try std.testing.expectEqual(@as(?bool, false), parse(""));
    try std.testing.expectEqual(@as(?bool, false), parse("0"));
    try std.testing.expectEqual(@as(?bool, true), parse("1"));
    for ([_][]const u8{ "2", "on", "true", "-1", " 1", "1 " }) |t| {
        try std.testing.expectEqual(@as(?bool, null), parse(t));
        try std.testing.expectError(error.BadTapsPacked, fromText(t));
    }
}

test "the planar planes gathered side by side land where the packed write lands" {
    // a small shape standing in for [cap, taps, D]: the writes' values are opaque to the layouts
    const cap: usize = 5;
    const ntaps: usize = 3;
    const d: usize = 4;
    const n: usize = 4; // the chunk's rows (the completion copy's extent)
    var planar: [ntaps * cap * d]u16 = undefined;
    var copied: [cap * ntaps * d]u16 = @splat(0);
    var direct: [cap * ntaps * d]u16 = @splat(0); // the packed write's result ("packed" is a keyword here)
    for (0..ntaps) |j| for (0..n) |i| for (0..d) |k| {
        const v: u16 = @intCast(j * 1000 + i * 10 + k);
        planar[planarElem(j, i, k, cap, d)] = v;
        direct[packedElem(j, i, k, ntaps, d)] = v;
    };
    // the completion copy: every tap's n rows, one row of D bytes at a time (Model.sliceRun's copyRows)
    for (0..ntaps) |j| for (0..n) |i| for (0..d) |k| {
        copied[packedElem(j, i, k, ntaps, d)] = planar[planarElem(j, i, k, cap, d)];
    };
    try std.testing.expectEqualSlices(u16, direct[0 .. n * ntaps * d], copied[0 .. n * ntaps * d]);
}

