// The indexer's head weights (model.py attention_k): wts = wl.to(bf16) * s, wl fp32: rounded to bf16, then times the
// Python scalar as torch's mul with a scalar computes it (fp32 opmath: float(bf16) * float(s)), rounded to bf16 again.
extern "C" __global__ void tf_ds_bf16_scale_kernel(const float* in, __nv_bfloat16* out, uint64_t count, float s, int pdl) {
    pdl_enter(pdl);
    for (uint64_t i = uint64_t(blockIdx.x) * blockDim.x + threadIdx.x; i < count; i += uint64_t(gridDim.x) * blockDim.x)
        out[i] = __float2bfloat16_rn(__fmul_rn(__bfloat162float(__float2bfloat16_rn(in[i])), s));
}

// A DSpark tap as the prompt forward takes it, h.to(fp32).mean(1).to(bf16) over the 4 streams: torch's reduce_kernel
// over the middle dim (a thread an output: four accumulators from 0, one value each, combined in order; too few
// values a thread to split them over the block), times MeanOps' factor 0.25, rounded to bf16. h [rows, 4, D] bf16,
// out [rows, D] (row stride os).
extern "C" __global__ void tf_ds_hc_mean4_kernel(const __nv_bfloat16* h, __nv_bfloat16* out, long long os, int rows,
                                                 int D, int pdl) {
    pdl_enter(pdl);
    const long long total = (long long)rows * D;
    for (long long i = (long long)blockIdx.x * blockDim.x + threadIdx.x; i < total; i += (long long)gridDim.x * blockDim.x) {
        const long long r = i / D, d = i % D;
        const __nv_bfloat16* x = h + r * 4 * D + d;
        const float a0 = __fadd_rn(0.f, __bfloat162float(x[0]));
        const float a1 = __fadd_rn(0.f, __bfloat162float(x[D]));
        const float a2 = __fadd_rn(0.f, __bfloat162float(x[2 * D]));
        const float a3 = __fadd_rn(0.f, __bfloat162float(x[3 * D]));
        const float s = __fadd_rn(__fadd_rn(__fadd_rn(a0, a1), a2), a3);
        out[r * os + d] = __float2bfloat16_rn(__fmul_rn(s, 0.25f));
    }
}

// These three steps mirror the instructions and reduction order of the pinned kit.
__device__ __forceinline__ float tf_ds_kit_squares4(float a, float b, float c, float d) {
    float sum = __fmul_rn(b, b);
    sum = __fmaf_rn(a, a, sum);
    sum = __fmaf_rn(c, c, sum);
    return __fmaf_rn(d, d, sum);
}

__device__ __forceinline__ float tf_ds_kit_warp_sum(float sum) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        sum = __fadd_rn(sum, __shfl_xor_sync(0xffffffffu, sum, offset));
    return sum;
}

template<int D>
__device__ __forceinline__ float tf_ds_kit_inverse_rms(float sum, float eps) {
    const float mean_eps = __fmaf_rn(sum, 1.0f / D, eps);
    float root, inv;
    asm("sqrt.approx.ftz.f32 %0, %1;" : "=f"(root) : "f"(mean_eps));
    asm("div.approx.f32 %0, %1, %2;" : "=f"(inv) : "f"(1.0f), "f"(root));
    return inv;

