fn dtypeBytes(name: []const u8) usize {
    if (std.mem.eql(u8, name, "float32") or std.mem.eql(u8, name, "int32")) return 4;
    if (std.mem.eql(u8, name, "int64")) return 8;
    return 2;
}

fn numel(shape: []const i64) usize {
    var n: usize = 1;
    for (shape) |s| n *= @intCast(s);
    return n;
}

