    ok: bool = true,

    /// The host row buffer for n fp32 values (made once, grown when wider).
    fn rowBuf(r: *Run, n: usize) ![]f32 {
        if (r.row.len < n) r.row = try r.a.alloc(f32, n); // the arena: no free
        return r.row[0..n];
    }

    /// Our buffer `dev` against fixture point `p`: the same bytes (sha256), or where they first differ.
    fn check(r: *Run, label: []const u8, p: ?*const Point, dev: u64) !bool {
        const pt = (try r.point(label, p)) orelse return false;
        try r.s.synchronize();
        const bytes = numel(pt.shape) * dtypeBytes(pt.dtype);
        if (bytes > r.host.len) r.host = try r.a.alloc(u8, bytes); // the arena: no free
        try r.d.check(r.d.api.cuMemcpyDtoH_v2(r.host.ptr, dev, bytes), "cuMemcpyDtoH");
        return r.finish(label, pt, bytes);
    }

    /// TF_DS_TAPS_PACKED's tap j: our buffer `dev`'s rows of the fixture's row width at row stride `row_stride`
    /// bytes (tap j's columns of the packed rows), gathered row by row into the host buffer before the digest.
    fn checkStrided(r: *Run, label: []const u8, p: ?*const Point, dev: u64, row_stride: usize) !bool {
        const pt = (try r.point(label, p)) orelse return false;
        try r.s.synchronize();
        const rows: usize = @intCast(pt.shape[0]);
        const row_bytes = numel(pt.shape[1..]) * dtypeBytes(pt.dtype);
        const bytes = rows * row_bytes;
        if (bytes > r.host.len) r.host = try r.a.alloc(u8, bytes); // the arena: no free
        for (0..rows) |i| try r.d.check(r.d.api.cuMemcpyDtoH_v2(r.host.ptr + i * row_bytes, dev + i * row_stride, row_bytes), "cuMemcpyDtoH");
        return r.finish(label, pt, bytes);
    }

    /// The fixture point to compare against; its absence is a reported failure.
    fn point(r: *Run, label: []const u8, p: ?*const Point) !?*const Point {
        if (p == null) {
            try r.out.print("{{\"rank\": {d}, \"point\": \"{s}\", \"error\": \"no fixture\"}}\n", .{ r.rank, label });
            try r.out.flush();
            r.ok = false;
        }
        return p;
    }

    /// The host buffer's first `bytes` bytes (downloaded) against `pt`'s digest.
    fn finish(r: *Run, label: []const u8, pt: *const Point, bytes: usize) !bool {
